import sys

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    constraints = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        l, r, x = data[i], data[i + 1], data[i + 2]
        if l == r:
            print(0)
            return
        constraints[l - 1].append((x - 1, r - 1))
    del data

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][r] counts valid permutations on [l,r), divided by (r-l)!.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1

    # For the current left endpoint, bound[x] is the smallest right
    # endpoint of a condition at x whose left endpoint is at least l.
    bound = [n] * n
    for l in range(n - 1, -1, -1):
        for x, r in constraints[l]:
            if r < bound[x]:
                bound[x] = r
        row = dp[l]
        for r in range(l, n):
            total = 0
            end = r + 1
            for k in range(l, end):
                if bound[k] > r:
                    total += row[k] * dp[k + 1][end]
            row[end] = total * inv[end - l] % MOD

    answer = dp[0][n]
    for i in range(2, n + 1):
        answer = answer * i % MOD
    print(answer)


if __name__ == '__main__':
    main()

