import sys
from collections import deque

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    deg = [0] * n
    for v in a:
        deg[v] += 1
    q = deque(i for i in range(n) if deg[i] == 0)
    dp = [None] * n
    while q:
        u = q.popleft()
        v = a[u]
        d, p = dp[u], dp[v]
        if d is None:
            if p is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    p[j] = p[j] * (j + 1) % MOD
        elif p is None:
            s = 0
            for j in range(m):
                s = (s + d[j]) % MOD
                d[j] = s
            dp[v] = d
        else:
            s = 0
            for j in range(m):
                s = (s + d[j]) % MOD
                p[j] = p[j] * s % MOD
        dp[u] = None
        deg[v] -= 1
        if deg[v] == 0:
            q.append(v)
    ans = 1
    for i in range(n):
        if deg[i] == 0:
            continue
        acc = None
        u = i
        while deg[u]:
            deg[u] = 0
            d = dp[u]
            if d is not None:
                if acc is None:
                    acc = d
                else:
                    for j in range(m):
                        acc[j] = acc[j] * d[j] % MOD
            dp[u] = None
            u = a[u]
        ways = m if acc is None else sum(acc) % MOD
        ans = ans * ways % MOD
    print(ans)

if __name__ == '__main__':
    main()

