import sys
from math import gcd

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                factors.setdefault(p, []).append((i, e))
            p += 1
        if x > 1:
            factors.setdefault(x, []).append((i, 1))

    answer = 1
    for p, events in factors.items():
        g = 0
        for _, e in events:
            g = gcd(g, e)
        base = pow(p, g, MOD)
        exponents = [0] * (n - 1)
        for i, e in events:
            exponents[i] = e // g

        limit = max(sum(exponents), n * max(exponents))
        powers = [1] * (limit + 1)
        for j in range(limit):
            powers[j + 1] = powers[j] * base % MOD

        # State: last exponent above the minimum exponent seen so far.
        dp = [1]
        for count, e in enumerate(exponents, 1):
            if e == 0:
                dp = [value * powers[h] % MOD for h, value in enumerate(dp)]
                continue
            nd = [0] * (len(dp) + e)
            for h, value in enumerate(dp):
                if not value:
                    continue
                # Ascending order means this destination has not been used yet.
                nd[h + e] = value * powers[h + e] % MOD
                if h >= e:
                    k = h - e
                    nd[k] = (nd[k] + value * powers[k]) % MOD
                else:
                    # A new minimum raises all previous exponents.
                    nd[0] = (nd[0] + value * powers[count * (e - h)]) % MOD
            dp = nd
        answer = answer * (sum(dp) % MOD) % MOD
    print(answer)

if __name__ == '__main__':
    main()

