import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    a = data[1:]
    m = max(a)

    # The Grundy value is the number of prime factors with multiplicity.
    omega = bytearray(m + 1)
    for p in range(2, m + 1):
        if omega[p] == 0:
            power = p
            while power <= m:
                for j in range(power, m + 1, power):
                    omega[j] += 1
                power *= p

    nim = 0
    for x in a:
        nim ^= omega[x]
    print('Anna' if nim else 'Bruno')


if __name__ == '__main__':
    main()

