    edges = [(next(it) - 1, next(it) - 1, next(it)) for _ in range(m)]
    queries = []
    closed = [False] * m
    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it) - 1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, next(it) - 1, next(it) - 1))

    inf = 10**18
    d = [[inf] * n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, c) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = c

    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in range(n):
                z = v + dk[j]
                if z < di[j]:
                    di[j] = z

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            z = d[query[1]][query[2]]
            answers.append(str(z if z < inf else -1))
        else:
            a, b, c = edges[query[1]]
            if c >= d[a][b]:
                continue
            da = d[a][:]
            db = d[b][:]
            for i in range(n):
