import sys
from math import gcd


def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    budget = next(it)
    processes = []
    hi = 100 * budget + 1

    for _ in range(n):
        a, p, b, q = next(it), next(it), next(it), next(it)
        # S has at least as much capacity per yen as T.
        if a * q < b * p:
            a, p, b, q = b, q, a, p
        hi = min(hi, budget * a // p + 1)

        # a/g T machines can be replaced by b/g S machines
        # without increasing the cost or changing capacity.
        options = [(t * b, t * q) for t in range(1, a // gcd(a, b))]
        processes.append((a, p, options))

    def feasible(w):
        total = 0
        for a, p, options in processes:
            best = ((w + a - 1) // a) * p
            for capacity, cost in options:
                if cost >= best:
                    break
                remaining = w - capacity
                if remaining <= 0:
                    best = cost
                    break
                candidate = cost + ((remaining + a - 1) // a) * p
                if candidate < best:
                    best = candidate
            total += best
            if total > budget:
                return False
        return True

    lo = 0
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid
    print(lo)


if __name__ == '__main__':
    main()

