class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # depth[c] is the number of operations needed to reduce c to 1.
        depth = [0] * (length + 1)
        for c in range(2, length + 1):
            depth[c] = 1 + depth[c.bit_count()]

        # dp[c] counts prefixes strictly smaller than s's current prefix,
        # with exactly c set bits. The equal prefix is tracked by ones.
        dp = [0] * (length + 1)
        ones = 0
        for i, bit in enumerate(s):
            for c in range(i + 1, 0, -1):
                dp[c] = (dp[c] + dp[c - 1]) % MOD
            if bit == '1':
                dp[ones] = (dp[ones] + 1) % MOD
                ones += 1

        return sum(dp[c] for c in range(1, length + 1)
                   if depth[c] < k) % MOD

