import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u = data[2 + 2 * i] - 1
        v = data[3 + 2 * i] - 1
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    pivots = []
    rank = 0
    for col in range(n):
        bit = 1 << col
        pivot = next((j for j in range(rank, n) if rows[j] & bit), -1)
        if pivot == -1:
            continue
        rows[rank], rows[pivot] = rows[pivot], rows[rank]
        for j in range(n):
            if j != rank and rows[j] & bit:
                rows[j] ^= rows[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [i for i in range(n) if i not in pivot_set]
    values = [0] * n
    for k, col in enumerate(free):
        values[col] = 1 << k
