from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd, even = (n + 1) // 2, n // 2
        remaining = list(range(1, n + 1))
        result = []
        required = 1 if n % 2 else -1

        while remaining:
            for i, value in enumerate(remaining):
                parity = value % 2
                if required != -1 and parity != required:
                    continue

                o = odd - parity
                e = even - (1 - parity)
                count = fact[o] * fact[e]
                if k > count:
                    k -= count
                else:
                    result.append(value)
                    remaining.pop(i)
                    odd, even = o, e
                    required = 1 - parity
                    break
            else:
                return []

        return result

