def main():
    it = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(it)
    k = next(it)

    # More than k copies of any one function can never be needed.
    counts = [0] * 2601
    for _ in range(n):
        a = next(it)
        b = next(it)
        idx = a * 51 + b
        if counts[idx] < k:
            counts[idx] += 1

    funcs = []
    for a in range(1, 51):
        for b in range(1, 51):
            c = counts[a * 51 + b]
            if c:
                funcs.append((a, b, c))

    # Apply functions from inner to outer in increasing (a - 1) / b.
    # With these small integer bounds, distinct ratios are well separated
    # compared with floating-point precision.
    funcs.sort(key=lambda f: (f[0] - 1) / f[1])

    dp = [-1] * (k + 1)
    dp[0] = 1
    used = 0
    for a, b, c in funcs:
        for _ in range(c):
            used = min(k, used + 1)
            for j in range(used, 0, -1):
                value = a * dp[j - 1] + b
                if value > dp[j]:
                    dp[j] = value

    print(dp[k])


