class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1

        answer = len(s)
        for target in range(1, max(counts) + 1):
            # Minimum cost so far when the previous letter is absent/present.
            absent = present = 0
            previous = 0
            for count in counts:
                new_absent = min(absent, present) + count
                if count < target:
                    deficit = target - count
                    # A surplus of the previous letter can fill this deficit
                    # with one change instead of a deletion and insertion.
                    new_present = deficit + min(
                        absent - min(previous, deficit),
                        present - min(max(previous - target, 0), deficit)
                    )
                else:
                    new_present = min(absent, present) + count - target
                absent, present = new_absent, new_present
                previous = count
            answer = min(answer, absent, present)
        return answer

