class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w))
            adj[v].append((u, w))

        if all(len(neighbors) <= k for neighbors in adj):
            return sum(edge[2] for edge in edges)

        parent = [-1] * n
        order = [0]
        for u in order:
            for v, w in adj[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        # free: parent edge absent; bound: parent edge present.
        free = [0] * n
        bound = [0] * n
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in adj[u]:
                if v != parent[u]:
                    base += free[v]
                    gain = w + bound[v] - free[v]
                    if gain > 0:
                        gains.append(gain)
            gains.sort(reverse=True)
            value = base + sum(gains[:k])
            free[u] = value
            bound[u] = value - (gains[k - 1] if len(gains) >= k else 0)

        return free[0]

