        if not hand:
            return False
        table = full ^ (hand | opponent)
        cards = hand
        while cards:
            card = cards & -cards
            cards -= card
            remaining = hand ^ card
            if not win(opponent, remaining):
                return True
            choices = table & lower[card]
            while choices:
                take = choices & -choices
                choices -= take
                if not win(opponent, remaining | take):
                    return True
        return False

