MOD = 998244353


def solve(h, w, rows):
    n = h + w
    parent = [-1] * n
    parity = [0] * n

    def find(x):
        value = 0
        while parent[x] >= 0:
            value ^= parity[x]
            x = parent[x]
        return x, value

    col = [0] * w
    components = n
    for i, row in enumerate(rows):
        p = 0
        for j, ch in enumerate(row):
            if ch == 65:
                p ^= 1
                col[j] ^= 1
            else:
                r, a = find(i)
                s, b = find(h + j)
                d = 1 ^ p ^ col[j] ^ a ^ b
                if r == s:
                    if d:
                        return 0
                else:
                    if parent[r] > parent[s]:
                        r, s = s, r
                    parent[r] += parent[s]
                    parent[s] = r
                    parity[s] = d
                    components -= 1
        if p:
            return 0
    if any(col):
        return 0
    return pow(2, components, MOD)


