class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = [part for part in p.split('*') if part]
        if not parts:
            return 0
        if len(parts) == 1:
            return len(parts[0]) if parts[0] in s else -1

        def occurrences(t):
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        lists = [occurrences(t) for t in parts]
        if any(not a for a in lists):
            return -1
        lengths = list(map(len, parts))
        pointers = [0] * len(parts)
        best = len(s) + 1
        for start in lists[0]:
            end = start + lengths[0]
            for k in range(1, len(parts)):
                a = lists[k]
                j = pointers[k]
                while j < len(a) and a[j] < end:
                    j += 1
                pointers[k] = j
                if j == len(a):
                    return best if best <= len(s) else -1
                end = a[j] + lengths[k]
