import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    for i in range(2, len(data), 3):
        x, y, z = data[i] - 1, data[i + 1] - 1, data[i + 2]
        adj[x].append((y, z))
        adj[y].append((x, z))
    del data

    a = [-1] * n
    for root in range(n):
        if a[root] != -1:
            continue
        a[root] = 0
        comp = [root]
        values = []
        bits = 0
        for v in comp:
            av = a[v]
            values.append(av)
            bits |= av
            for w, z in adj[v]:
                want = av ^ z
                if a[w] == -1:
                    a[w] = want
                    comp.append(w)
                elif a[w] != want:
                    print(-1)
                    return

        size = len(comp)
        if size <= 2:
            continue
        mask = 0
        for b in range(bits.bit_length()):
            cnt = sum((v >> b) & 1 for v in values)
            if cnt * 2 > size:
                mask |= 1 << b
        if mask:
            for v in comp:
                a[v] ^= mask

    print(' '.join(map(str, a)))


