import sys


def solve(n, aa, bb):
    if aa == bb:
        return 0
    a = [i for i, c in enumerate(aa) if c == 49]
    b = [i for i, c in enumerate(bb) if c == 49]
    la = len(a)
    if len(b) > la:
        return -1
    first = b[0]
    last = b[-1]
    alast = a[-1]
    gaps = [b[i] - b[i - 1] for i in range(1, len(b))]

    def ok(k):
        end = first - k
        if a[0] < end:
            return False
        p = 0
        end = a[0] + ((a[0] - end) & 1)
        while p < la and a[p] <= end:
            p += 1
        for d in gaps:
            while p < la and a[p] < end + d:
                x = a[p]
                end = x + ((x - end) & 1)
                p += 1
                while p < la and a[p] <= end:
                    p += 1
            end += d
            if p == la:
                return False
            x = a[p]
            end = x + ((x - end) & 1)
            p += 1
            while p < la and a[p] <= end:
                p += 1
        end = max(end, alast + ((alast - end) & 1))
        return end <= last + k

    lower = max(abs(a[0] - first), abs(alast - last))
    if ok(lower):
        return lower
    lower += 1
    best = 2 * n + 2
    for parity in range(2):
        lo = (lower - parity + 1) // 2 - 1
        hi = (min(2 * n, best - 1) - parity) // 2
        if hi <= lo or not ok(2 * hi + parity):
            continue
        while hi - lo > 1:
            mid = (hi + lo) // 2
            if ok(2 * mid + parity):
                hi = mid
            else:
                lo = mid
        best = 2 * hi + parity
    return best if best <= 2 * n else -1


def main():
    data = sys.stdin.buffer.read().split()
    out = []
    for j in range(int(data[0])):
        z = 1 + 3 * j
        out.append(str(solve(int(data[z]), data[z + 1], data[z + 2])))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    main()

