import sys
import heapq


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)

    # dp[c] is the best happiness with capacity at most c.
    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        gains = []
        for _ in range(W // w):
            gain = -heap[0]
            if gain <= 0:
                break
            gains.append(gain)
            heapq.heapreplace(heap, 2 - gain)

        count = len(gains)
        if count <= 8:
            for gain in gains:
                for j in range(W, w - 1, -1):
                    value = dp[j - w] + gain
                    if value > dp[j]:
                        dp[j] = value
        else:
            prefix = [0]
            for gain in gains:
                prefix.append(prefix[-1] + gain)
            new = [0] * (W + 1)
            for r in range(w):
                a = dp[r::w]
                b = [0] * len(a)

                # Concavity of prefix makes maximizing indices monotone.
                def compute(left, right, optleft, optright):
                    if left > right:
                        return
                    mid = (left + right) // 2
                    lo = max(optleft, mid - count)
                    hi = min(mid, optright)
                    best = -1
                    arg = lo
                    for s in range(lo, hi + 1):
                        value = a[s] + prefix[mid - s]
                        if value > best:
                            best = value
                            arg = s
                    b[mid] = best
                    compute(left, mid - 1, optleft, arg)
                    compute(mid + 1, right, arg, optright)

                compute(0, len(a) - 1, 0, len(a) - 1)
                new[r::w] = b
            dp = new

    print(dp[W])


