from typing import List

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        seen = {}
        answer = 0
        # Sorting ensures a swap in the current number can also account
        # for pairs where removing leading zeros shortens the number.
        for x in sorted(nums):
            digits = [int(c) for c in str(x)][::-1]
            powers = [10 ** i for i in range(len(digits))]
            variants = {x}
            for i in range(len(digits)):
                for j in range(i):
                    variants.add(x + (digits[j] - digits[i]) * (powers[i] - powers[j]))
            answer += sum(seen.get(y, 0) for y in variants)
            seen[x] = seen.get(x, 0) + 1
        return answer

