from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        dp = [1 if x else 0 for x in nums]
        goals = [1 << x for x in nums]
        masks = [(1 << (x + 1)) - 1 for x in nums]
        remaining = sum(x > 0 for x in nums)
        if remaining == 0:
            return 0

        for k, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                if dp[i]:
                    bits = (dp[i] | (dp[i] << value)) & masks[i]
                    if bits & goals[i]:
                        dp[i] = 0
                        remaining -= 1
                    else:
                        dp[i] = bits
            if remaining == 0:
                return k
        return -1

