from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        # z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i < right:
                z[i] = min(right - i, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > right:
                left, right = i, i + z[i]

        dp = [0] * (n + 1)
        answer = 0
        for i in range(n - 2, 0, -1):
            limit = (n + i) // 2
            if z[i] >= i:
                # All second cut positions j >= 2*i satisfy condition 1.
                answer += max(0, n - 2 * i)
                limit = min(limit, 2 * i - 1)

            value = nums[i]
            # Ascending j preserves the previous row's dp[j + 1].
            for j in range(i + 1, n):
                if nums[j] == value:
                    common = dp[j + 1] + 1
                    dp[j] = common
                    if j <= limit and common >= j - i:
                        answer += 1
                else:
                    dp[j] = 0

        return answer

