from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        positions = [[] for _ in range(26)]
        for j in range(len(pattern) - 1, -1, -1):
            positions[ord(pattern[j]) - 97].append(j)

        removable = bytearray(len(source))
        for i in targetIndices:
            removable[i] = 1

        # Minimum number of removable indices used to match each prefix.
        dp = [len(source) + 1] * (len(pattern) + 1)
        dp[0] = 0
        for i, char in enumerate(source):
            cost = removable[i]
            # Descending order prevents using this source character twice.
            for j in positions[ord(char) - 97]:
                candidate = dp[j] + cost
                if candidate < dp[j + 1]:
                    dp[j + 1] = candidate

        return len(targetIndices) - dp[-1]

