        transitions = []
        for a, b in states:
            prev = [k for k, (c, d) in enumerate(states)
                    if a != c and b != d]
            transitions.append((a, b, *prev))

        dp = [cost[0][a] + cost[n - 1][b] for a, b in states]
        for i in range(1, n // 2):
            left, right = cost[i], cost[n - 1 - i]
            dp = [left[a] + right[b] + min(dp[x], dp[y], dp[z])
                  for a, b, x, y, z in transitions]
        return min(dp)

