import re

class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        zero_runs = re.findall(r'0+', s)
        best_gain = 0
        for i in range(1, len(zero_runs)):
            best_gain = max(
                best_gain,
                len(zero_runs[i - 1]) + len(zero_runs[i])
            )
        return s.count('1') + best_gain

